    {id:'sales',title:'Продажи',icon:ChartColumn,onItemClick:() => changeMode('sales')},
    {id:'monitoring',title:'Мониторинг',icon:Pulse,onItemClick:() => changeMode('monitoring')},
    {id:'sources',title:'Источники данных',icon:Database,onItemClick:() => setPanel('source')},
  ]} renderFooter={() => <div className=\"nav-footer\"><Button view=\"flat\" title=\"Справка\" aria-label=\"Справка\" onClick={() => setPanel('help')}><Icon data={CircleQuestion} size={20}/></Button><Button view=\"flat\" title=\"Настройки\" aria-label=\"Настройки\" onClick={() => setPanel('settings')}><Icon data={Gear} size={20}/></Button><div className=\"nav-avatar\" title=\"Рабочее пространство Аналитика\">А</div></div>} renderContent={() => <div className=\"workspace\">
    <header className=\"topbar\"><div className=\"topbar-left\"><span className=\"wordmark\">pulse<span>.</span></span><span className=\"topbar-divider\"/><span className=\"workspace-name\">Рабочее пространство</span><Icon data={ChevronRight} size={13}/><span className=\"breadcrumb-current\">Аналитика</span></div><div className=\"topbar-right\"><span className=\"environment\"><span className=\"status-dot\"/>Все системы работают</span><Button view=\"flat\" aria-label=\"Уведомления\" title=\"Уведомления\" onClick={() => setPanel('notifications')}><Icon data={Bell} size={18}/></Button><div className=\"profile-avatar\">АК</div></div></header>
    <main className=\"main-content\"><div className=\"page-heading\"><div><div className=\"eyebrow\">ВАШ БИЗНЕС В ЦИФРАХ</div><Text as=\"h1\" variant=\"display-2\">Обзор аналитики</Text><p className=\"page-description\">Вся картина в одном месте. От продаж до состояния систем.</p></div><div className=\"page-actions\"><Button size=\"l\" view=\"outlined\" title={saved ? 'Удалить из избранного' : 'Сохранить виджет'} aria-label={saved ? 'Удалить из избранного' : 'Сохранить виджет'} selected={saved} onClick={() => {setSaved("'!saved); setNotice(saved ? '"'Виджет удалён из избранного' : 'Виджет добавлен в избранное');}}><Icon data={saved ? BookmarkFill : Bookmark} size={17}/></Button><Button size=\"l\" view=\"action\" onClick={download}><Icon data={ArrowDownToLine} size={16}/>Экспорт данных</Button></div></div>
    <div className=\"overview-bar\"><div className=\"overview-label\"><Icon data={LayoutCells} size={15}/><span>Обзор</span><span className=\"count-badge\">1 виджет</span></div><div className=\"refresh-controls\"><span className=\"update-time\">Обновлено в {updated.toLocaleTimeString('ru-RU', {hour:'2-digit',minute:'2-digit'})}</span>{"'!isSales && <Switch checked={live} onUpdate={setLive} size="s">Авто</Switch>}<Button view="flat" size="s" title="Обновить данные" aria-label="Обновить данные" loading={refreshing} onClick={refresh}><Icon data={ArrowsRotateRight} size={15}/></Button></div></div>
    {!fullscreen && chartCard}
    <div className="bottom-panels"><section className="insight-panel"><div className="insight-icon"><Icon data={isSales ? ChartLine : Pulse} size={21}/></div><div className="insight-copy"><div className="insight-heading">{isSales ? '"'Хороший темп. Продолжайте в том же духе.' : 'Сервис работает стабильно.'}<span className=\"insight-tag\">{isSales ? 'Рост продаж' : 'Состояние системы'}</span></div><p>{isSales ? <>Выручка выросла на <strong>{number(growth, 1)}%</strong> относительно прошлого периода.<br/>Лучший день — <strong>{date(best.timestamp)}</strong>: {number(best.value)} ₽.</> : <>Среднее время ответа — <strong>{number(mean)} мс</strong>, при целевом пороге 300 мс.<br/>За выбранный период собрано {number(monitoringPoints.length)} измерений.</>}</p></div><span className=\"insight-decoration\" aria-hidden=\"true\">↗</span></section><section className=\"source-panel\"><div className=\"source-panel-top\"><span className=\"source-icon\"><Icon data={Database} size={17}/></span><span>Источник данных</span><span className=\"connected\"><span className=\"status-dot\"/>Подключён</span></div><div className=\"source-panel-bottom\"><div><strong>{isSales ? 'Магазин · Основной' : 'API · Production'}</strong><span>Демонстрационный набор данных</span></div><Button view=\"flat\" size=\"s\" aria-label=\"Открыть источник данных\" title=\"Открыть источник данных\" onClick={() => setPanel('source')}><Icon data={ChevronRight} size={17}/></Button></div></section></div>
    <footer className=\"page-footer\"><span>Меньше шума. Больше ясности.</span><span><span className=\"footer-pulse\">pulse</span> analytics <span className=\"footer-dot\">·</span> Время в UTC</span></footer>
    </main></div>}/></div>
    <Modal open={fullscreen} onClose={() => setFullscreen(false)} contentClassName=\"expanded-modal\" aria-label=\"График на весь экран\">{fullscreen && chartCard}</Modal>
    <Modal open={panel "'!== null} onClose={() => setPanel(null)} aria-label="Информация о виджете"><div className="info-modal"><div className="modal-heading"><Text variant="header-1">{panel === '"'settings' ? 'Настройки виджета' : panel === 'source' ? 'Источник данных' : panel === 'notifications' ? 'Уведомления' : 'Как пользоваться виджетом'}</Text><Button view=\"flat\" aria-label=\"Закрыть\" onClick={() => setPanel(null)}><Icon data={Xmark}/></Button></div>
      {panel === 'settings' ? <><div className=\"settings-row\"><span className=\"icon-label\"><Icon data={dark ? Moon : Sun}/>Тёмная тема</span><Switch checked={dark} onUpdate={value => setTheme(value ? 'dark' : 'light')}/></div><div className=\"settings-row\"><div>Автообновление мониторинга<p className=\"subtle\">Новые измерения каждые 5 секунд</p></div><Switch checked={live} onUpdate={setLive}/></div><div className=\"settings-row\"><span>Сравнение периодов</span><Switch checked={compare} onUpdate={setCompare}/></div></> : panel === 'source' ? <><div className=\"modal-status\"><Icon data={CircleCheck} size={20}/>Демонстрационный источник активен</div><p>Виджет использует локальные демонстрационные данные. Продажи доступны за 7, 30 и 90 дней. Мониторинг генерирует измерения с шагом 10 секунд и обновляет окно каждые 5 секунд.</p><dl className=\"source-details\"><dt>Источник</dt><dd>{isSales ? 'Магазин · Основной' : 'API · Production'}</dd><dt>Часовой пояс</dt><dd>UTC</dd><dt>Точек в текущем ряду</dt><dd>{number(allSeries[0].points.length)}</dd></dl><Button view=\"action\" onClick={download}><Icon data={ArrowDownToLine}/>Скачать текущие данные</Button></> : panel === 'notifications' ? <div className=\"notification-content\"><Icon data={CircleCheck} size={32}/><Text variant=\"subheader-2\">Всё под контролем</Text><p className=\"subtle\">Новых уведомлений нет. Демонстрационные данные доступны в обоих режимах.</p></div> : <><p>Переключайтесь между продажами и мониторингом в верхней части виджета.</p><ul className=\"help-list\"><li>Выберите период и показатель для анализа.</li><li>Наведите курсор на график, чтобы увидеть точные значения.</li><li>Включите сравнение с предыдущим периодом.</li><li>В мониторинге выделите участок графика для увеличения. Двойной щелчок сбрасывает масштаб.</li><li>Кнопка «Экспорт данных» сохраняет серии в CSV.</li></ul></>}
    </div></Modal>
    {notice && <div className=\"toast\" role=\"status\"><Icon data={CircleCheck} size={18}/>{notice}<Button view=\"flat\" size=\"s\" onClick={() => setNotice('')} aria-label=\"Закрыть уведомление\"><Icon data={Xmark} size={14}/></Button></div>}
  </>;
}
EOF"

args.command:
/bin/bash -lc "cat > src/styles.css <<'EOF'
/* Brand tokens are defined together so controls, focus and charts stay consistent. */
.g-root_theme_light {
  --g-color-base-brand: #7860df;
  --g-color-base-brand-hover: #6b51d2;
  --g-color-base-selection: #f0ecfc;
  --g-color-base-selection-hover: #e8e1fa;
  --g-color-line-brand: #7860df;
  --g-color-text-brand: #785ddd;
  --g-color-text-brand-contrast: #ffffff;
  --g-color-text-link: #785ddd;
  --g-color-text-link-hover: #6347c9;
  --g-color-line-focus: #947ee9;
  --app-background: #f8f9fb;
  --app-chart-comparison: #c7b9ef;
  --app-insight-background: #f4f1fc;
  --app-insight-border: #e9e2f7;
  --app-green-background: #edf7f1;
  --app-green-text: #378362;
  --app-soft-foreground: #70717e;
  --g-color-line-generic: #eaeaf0;
  --g-color-text-primary: #252735;
  --g-color-text-secondary: #858591;
}
.g-root_theme_dark {
  --g-color-base-brand: #9c85ef;
  --g-color-base-brand-hover: #ad98f6;
  --g-color-base-selection: #373047;
  --g-color-base-selection-hover: #443857;
  --g-color-line-brand: #9c85ef;
  --g-color-text-brand: #b19cf8;
  --g-color-text-brand-contrast: #1b152d;
  --g-color-text-link: #b19cf8;
  --g-color-text-link-hover: #c7b6ff;
  --g-color-line-focus: #b19cf8;
  --app-background: #18191e;
  --app-chart-comparison: #6e5d98;
  --app-insight-background: #292333;
  --app-insight-border: #3c304d;
  --app-green-background: #23392d;
  --app-green-text: #7ac49e;
  --app-soft-foreground: #b8b6c4;
}
.g-root {
  --g-font-family-sans: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --g-text-display-2-font-size: 32px;
  --g-text-display-2-line-height: 42px;
  --g-text-display-1-font-size: 28px;
  --g-text-display-1-line-height: 36px;
  --g-text-subheader-3-font-size: 19px;
  --g-button-border-radius: var(--g-border-radius-m);
  --g-border-radius-xl: 14px;
}
* {box-sizing: border-box;}
body {margin: 0; min-width: 320px; background: var(--app-background); -webkit-font-smoothing: antialiased;}
button, a, input { -webkit-tap-highlight-color: transparent; }
h1, h2, p {margin: 0;}
.app-shell {min-height: 100vh;}
.navigation {--gn-aside-header-min-width: 68px; --gn-aside-header-background-color: var(--g-color-base-background); --gn-aside-header-item-icon-background-size: 42px; --gn-aside-header-padding-top: 10px;}
.brand-mark {color: var(--g-color-base-brand);}
.nav-footer {display: flex; flex-direction: column; align-items: center; gap: var(--g-spacing-4); padding: var(--g-spacing-4) 0; color: var(--app-soft-foreground);}
.nav-avatar, .profile-avatar {display: flex; align-items: center; justify-content: center; flex-shrink: 0; width: 32px; height: 32px; border-radius: 50%; background: var(--g-color-base-selection); color: var(--g-color-text-brand); font-size: 11px; font-weight: 600;}
.nav-avatar {background: var(--g-color-base-generic); color: var(--g-color-text-primary);}
.workspace {min-width: 0; background: var(--app-background); min-height: 100vh;}
.topbar {height: 72px; padding: 0 var(--g-spacing-8); background: var(--g-color-base-background); border-bottom: 1px solid var(--g-color-line-generic); display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4);}
.topbar-left, .topbar-right {display: flex; align-items: center; gap: var(--g-spacing-4);}
.topbar-left {min-width: 0; color: var(--g-color-text-secondary); font-size: 12px;}
.topbar-right {flex-shrink: 0; gap: var(--g-spacing-5);}
.wordmark {font-size: 26px; font-weight: 750; letter-spacing: -1.3px; color: var(--g-color-text-primary);}
.wordmark span {color: var(--g-color-text-brand);}
.topbar-divider {height: 21px; width: 1px; background: var(--g-color-line-generic); margin: 0 var(--g-spacing-2);}
.breadcrumb-current {color: var(--g-color-text-primary);}
.environment {display: flex; align-items: center; gap: var(--g-spacing-2); font-size: 11px; color: var(--g-color-text-secondary);}
.status-dot {width: 6px; height: 6px; border-radius: 50%; display: inline-block; background: var(--app-green-text); flex-shrink: 0;}
.main-content {max-width: 1440px; padding: var(--g-spacing-10) var(--g-spacing-10) 0; margin: 0 auto;}
.page-heading {display: flex; justify-content: space-between; gap: var(--g-spacing-5); align-items: center; margin-bottom: var(--g-spacing-8);}
.eyebrow {font-size: 10px; letter-spacing: 1.7px; font-weight: 600; color: var(--g-color-text-secondary); margin-bottom: var(--g-spacing-2);}
.page-heading h1 {font-weight: 600; letter-spacing: -1.2px;}
.page-description {margin-top: var(--g-spacing-2); font-size: 13px; color: var(--app-soft-foreground); line-height: 21px;}
.page-actions {display: flex; align-items: center; gap: var(--g-spacing-2); padding-top: var(--g-spacing-3); flex-shrink: 0;}
.page-actions .g-button {font-size: 12px;}
.overview-bar {display: flex; align-items: center; justify-content: space-between; margin-bottom: var(--g-spacing-4); gap: var(--g-spacing-4);}
.overview-label {display: flex; align-items: center; gap: var(--g-spacing-2); font-weight: 500; font-size: 12px;}
.overview-label > svg {color: var(--app-soft-foreground);}
.count-badge {margin-left: var(--g-spacing-2); border: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-1) var(--g-spacing-2); border-radius: var(--g-border-radius-s); background: var(--g-color-base-background); color: var(--g-color-text-secondary); font-size: 10px; font-weight: 400;}
.refresh-controls {display: flex; gap: var(--g-spacing-3); align-items: center; color: var(--g-color-text-secondary);}
.update-time {font-size: 11px;}
.chart-card {overflow: hidden; border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); background: var(--g-color-base-background); box-shadow: 0 2px 4px color-mix(in srgb, var(--g-color-sfx-shadow) 18%, transparent);}
.widget-tabs-row {display: flex; align-items: center; justify-content: space-between; padding: var(--g-spacing-4) var(--g-spacing-6); gap: var(--g-spacing-3); border-bottom: 1px solid var(--g-color-line-generic);}
.mode-switch {--g-segmented-radio-group-border-radius: var(--g-border-radius-m); --g-segmented-radio-group-background-color: var(--app-background); --g-segmented-radio-group-option-checked-text-color: var(--g-color-text-brand); --g-segmented-radio-group-option-checked-background-color: var(--g-color-base-background);}
.icon-label {display: inline-flex; align-items: center; gap: var(--g-spacing-2);}
.data-status {display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--g-color-text-secondary); font-size: 11px;}
.status-divider {height: 16px; width: 1px; background: var(--g-color-line-generic); margin-left: var(--g-spacing-3); margin-right: var(--g-spacing-1);}
.widget-body {padding: var(--g-spacing-6) var(--g-spacing-7) var(--g-spacing-3);}
.chart-heading-row {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4);}
.chart-heading-row h2 {font-weight: 600; letter-spacing: -.4px;}
.subtle {color: var(--g-color-text-secondary); font-size: 12px; line-height: 1.6;}
.chart-subtitle {margin-top: var(--g-spacing-1); font-size: 11px;}
.chart-heading-actions {display: flex; align-items: center; gap: var(--g-spacing-3); color: var(--app-soft-foreground);}
.demo-badge {border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-s); padding: var(--g-spacing-1) var(--g-spacing-2); color: var(--g-color-text-secondary); font-size: 10px;}
.metrics {display: grid; grid-template-columns: 1.2fr 1fr 1fr 1.05fr; margin: var(--g-spacing-7) 0 var(--g-spacing-7);}
.metric {padding: var(--g-spacing-1) var(--g-spacing-5); border-left: 1px solid var(--g-color-line-generic); min-width: 0;}
.metric:first-child {border: 0; padding-left: 0;}
.metric:last-child {padding-right: 0;}
.metric-label {display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--app-soft-foreground); font-size: 11px; margin-bottom: var(--g-spacing-2);}
.metric-label svg {color: var(--g-color-text-secondary); opacity: .65;}
.metric-value {display: block; font-weight: 550; letter-spacing: -.9px; white-space: nowrap; font-variant-numeric: tabular-nums;}
.metric-bottom {display: flex; align-items: center; flex-wrap: wrap; gap: var(--g-spacing-2); margin-top: var(--g-spacing-2);}
.metric-change {display: inline-flex; align-items: center; gap: 2px; color: var(--app-green-text); background: var(--app-green-background); border-radius: var(--g-border-radius-xs); padding: 2px var(--g-spacing-1); font-weight: 500; font-size: 10px; white-space: nowrap;}
.metric-note {color: var(--g-color-text-secondary); font-size: 10px; white-space: nowrap;}
.chart-toolbar {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); padding-top: var(--g-spacing-5); border-top: 1px solid var(--g-color-line-generic);}
.toolbar-start, .toolbar-end {display: flex; align-items: center; gap: var(--g-spacing-3); min-width: 0;}
.toolbar-end {flex-wrap: wrap; justify-content: flex-end;}
.toolbar-separator {height: 16px; width: 1px; background: var(--g-color-line-generic);}
.date-range {display: flex; align-items: center; justify-content: center; gap: var(--g-spacing-2); border: 1px solid var(--g-color-line-generic); height: 30px; border-radius: var(--g-border-radius-m); padding: 0 var(--g-spacing-3); color: var(--app-soft-foreground); white-space: nowrap; font-size: 11px;}
.chart-unit {color: var(--g-color-text-secondary); font-size: 10px; padding: var(--g-spacing-5) 0 0;}
.plot-area {height: 308px; margin-top: var(--g-spacing-1); width: 100%; min-width: 0;}
.chart-engine {height: 100%; width: 100%;}
.chart-state {display: flex; height: 100%; min-height: 240px; align-items: center; justify-content: center; flex-direction: column; gap: var(--g-spacing-4); color: var(--g-color-text-secondary); font-size: 13px;}
.chart-state strong {color: var(--g-color-text-primary);}
.chart-legend {display: flex; align-items: center; justify-content: center; gap: var(--g-spacing-5); padding: var(--g-spacing-2) 0 var(--g-spacing-2); font-size: 11px; color: var(--app-soft-foreground);}
.legend-line {display: inline-block; width: 19px; height: 0; border-top: 3px solid var(--g-color-text-brand); border-radius: var(--g-border-radius-xs); margin-right: var(--g-spacing-2); vertical-align: middle;}
.legend-previous {border-color: var(--app-chart-comparison); border-top-style: dashed; border-top-width: 2px;}
.legend-item {display: inline-flex; align-items: center;}
.legend-muted {opacity: .4;}
.widget-footer {display: flex; justify-content: space-between; align-items: center; padding: var(--g-spacing-4) var(--g-spacing-7); border-top: 1px solid var(--g-color-line-generic); color: var(--g-color-text-secondary); gap: var(--g-spacing-4); font-size: 11px; background: color-mix(in srgb, var(--app-background) 55%, var(--g-color-base-background));}
.widget-footer .g-switch {--g-switch-text-color: var(--app-soft-foreground); font-size: 11px;}
.bottom-panels {display: grid; grid-template-columns: 1.75fr 1fr; gap: var(--g-spacing-5); margin-top: var(--g-spacing-5);}
.insight-panel {display: flex; position: relative; overflow: hidden; gap: var(--g-spacing-4); align-items: flex-start; padding: var(--g-spacing-5); border: 1px solid var(--app-insight-border); border-radius: var(--g-border-radius-l); background: var(--app-insight-background);}
.insight-icon {display: flex; align-items: center; justify-content: center; width: 36px; height: 36px; flex-shrink: 0; color: var(--g-color-text-brand); background: var(--g-color-base-background); border: 1px solid var(--app-insight-border); border-radius: var(--g-border-radius-m);}
.insight-copy {position: relative; z-index: 1; min-width: 0;}
.insight-heading {display: flex; flex-wrap: wrap; align-items: center; gap: var(--g-spacing-3); font-size: 12px; font-weight: 550; margin-top: var(--g-spacing-1);}
.insight-tag {font-size: 9px; font-weight: 500; padding: 2px var(--g-spacing-2); border-radius: var(--g-border-radius-s); border: 1px solid var(--app-insight-border); color: var(--g-color-text-brand);}
.insight-copy p {margin-top: var(--g-spacing-2); color: var(--app-soft-foreground); font-size: 11px; line-height: 20px;}
.insight-copy strong {font-weight: 600; color: var(--g-color-text-primary);}
.insight-decoration {position: absolute; right: 12px; bottom: -8px; font-size: 100px; line-height: 1; font-weight: 200; color: var(--g-color-text-brand); opacity: .08;}
.source-panel {padding: var(--g-spacing-4) var(--g-spacing-5); background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l);}
.source-panel-top {display: flex; align-items: center; gap: var(--g-spacing-2); font-size: 11px; color: var(--app-soft-foreground);}
.source-icon {display: inline-flex; color: var(--g-color-text-secondary);}
.connected {display: inline-flex; align-items: center; gap: var(--g-spacing-1); margin-left: auto; font-size: 9px; color: var(--app-green-text); background: var(--app-green-background); padding: 2px var(--g-spacing-2); border-radius: var(--g-border-radius-s);}
.connected .status-dot {width: 4px; height: 4px;}
.source-panel-bottom {display: flex; align-items: center; justify-content: space-between; margin-top: var(--g-spacing-4); gap: var(--g-spacing-2);}
.source-panel-bottom strong {display: block; font-size: 12px; font-weight: 550;}
.source-panel-bottom span {display: block; font-size: 10px; color: var(--g-color-text-secondary); margin-top: var(--g-spacing-1);}
.page-footer {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-3); padding: var(--g-spacing-6) 0; color: var(--g-color-text-secondary); font-size: 10px;}
.footer-pulse {font-weight: 700; letter-spacing: -.4px; color: var(--app-soft-foreground); font-size: 13px;}
