.count-badge {margin-left: var(--g-spacing-2); border: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-1) var(--g-spacing-2); border-radius: var(--g-border-radius-s); background: var(--g-color-base-background); color: var(--g-color-text-secondary); font-size: 10px; font-weight: 400;}
