.status-divider {height: 16px; width: 1px; background: var(--g-color-line-generic); margin-left: var(--g-spacing-3); margin-right: var(--g-spacing-1);}
.widget-body {padding: var(--g-spacing-6) var(--g-spacing-7) var(--g-spacing-3);}
.chart-heading-row {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4);}
.chart-heading-row h2 {font-weight: 600; letter-spacing: -.4px;}
.subtle {color: var(--g-color-text-secondary); font-size: 12px; line-height: 1.6;}
.chart-subtitle {margin-top: var(--g-spacing-1); font-size: 11px;}
.chart-heading-actions {display: flex; align-items: center; gap: var(--g-spacing-3); color: var(--app-soft-foreground);}
.demo-badge {border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-s); padding: var(--g-spacing-1) var(--g-spacing-2); color: var(--g-color-text-secondary); font-size: 10px;}
.metrics {display: grid; grid-template-columns: 1.2fr 1fr 1fr 1.05fr; margin: var(--g-spacing-7) 0 var(--g-spacing-7);}
.metric {padding: var(--g-spacing-1) var(--g-spacing-5); border-left: 1px solid var(--g-color-line-generic); min-width: 0;}
.metric:first-child {border: 0; padding-left: 0;}
.metric:last-child {padding-right: 0;}
.metric-label {display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--app-soft-foreground); font-size: 11px; margin-bottom: var(--g-spacing-2);}
.metric-label svg {color: var(--g-color-text-secondary); opacity: .65;}
.metric-value {display: block; font-weight: 550; letter-spacing: -.9px; white-space: nowrap; font-variant-numeric: tabular-nums;}
